#!/usr/bin/env bash
# Generated by cloudcc. Builds a deployment artefact for each execution unit.
#
# Pulumi does not install dependencies for you, so this runs before
# `pulumi up`. `cloudcc deploy` invokes it automatically.
set -euo pipefail

here="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cd "$here"

build="build"
rm -rf "$build"
mkdir -p "$build"

echo "packaging execution unit dispatch"
unit_build="$build/dispatch"
mkdir -p "$unit_build"

# The bundler resolves imports against node_modules, so the unit's
# dependencies have to be on disk first.
#
# npm install, never npm ci: cloudcc adds the runtime's own dependencies to
# package.json, so any lockfile copied from the source tree no longer matches
# it and npm ci would refuse. The stale lockfile is removed for the same
# reason -- keeping it would only mislead.
if [ -f "dispatch/package.json" ]; then
  rm -f "dispatch/package-lock.json"
  ( cd "dispatch" && npm install --silent --omit=dev --no-audit --no-fund )
fi

# esbuild resolves and inlines the unit's dependencies, which sidesteps
# shipping node_modules in a zip -- the part of Node Lambda packaging that
# usually hurts. Native modules cannot be bundled; list them under
# `externals` in cloudcc.yaml if you have any.
bundler="npx --yes esbuild"
if command -v esbuild >/dev/null 2>&1; then
  bundler="esbuild"
fi

# The banner is not decoration. Bundling to ESM turns every CommonJS dependency
# into a module whose `require` esbuild replaces with a shim, and that shim
# throws for anything it did not bundle -- including Node's own builtins, which
# are external by definition. serverless-http reaches `require("http")` at load,
# so without this the bundle raises `Dynamic require of "node:https" is not
# supported` before the handler is ever called. Restoring a real `require` from
# import.meta.url is the standard remedy and costs one line in the output.
$bundler "dispatch/cloudcc_lambda_entry.mjs" \
  --bundle \
  --platform=node \
  --target=node22 \
  --format=esm \
  --banner:js="import { createRequire as __cloudccCreateRequire } from 'node:module'; const require = __cloudccCreateRequire(import.meta.url);" \
  --outfile="$unit_build/index.mjs" \
  --log-level=warning

# Deterministic zip: fixed timestamps and sorted entries, so an unchanged unit
# produces a byte-identical artefact and Pulumi sees no diff.
find "$unit_build" -exec touch -t 198001010000 {} +
( cd "$unit_build" && find . -type f | LC_ALL=C sort | zip -q -X -@ "../dispatch.zip" )
echo "  wrote $build/dispatch.zip"

